// Types for text-paras.js (the page imports the .js; the server and tests import it through these).
export type ListItem = { p: number; type: "bullet" | "number" | "none"; level: number };
export type ParaPlan = { before: number; first: number; rest: number; marker: string | null; markerX: number; hang?: boolean };
export const LIST_TYPES: string[];
export const MAX_LEVEL: number;
export const PARA_KEYS: string[];
export const LETTER_CASES: string[];
export const OPEN_QUOTES: string;
export function caseCss(n: Record<string, unknown> | null | undefined): { textTransform: string; fontFeatureSettings: string };
export function wordStarts(s: string): number[];
export function markerColor(n: Record<string, unknown> | null | undefined, content: string, at: number): string | null;
export function listStep(size: number): number;
export function paragraphStarts(content: string): number[];
export function paragraphCount(content: string): number;
export function paraAt(content: string, i: number): number;
export function listErrors(lists: unknown, count?: number): string[];
export function normalizeLists(lists: unknown, count?: number): ListItem[];
export function shiftLists(lists: ListItem[], before: string, at: number, removed: number, inserted: string): ListItem[];
export function followLists(lists: unknown, before: string, after: string): ListItem[];
export function markerText(type: string, level: number, n: number): string;
export function markers(lists: ListItem[], count: number): (string | null)[];
export function hasParagraphs(n: Record<string, unknown> | null | undefined): boolean;
export function paragraphPlan(n: Record<string, unknown>, content: string, size: number): ParaPlan[];
export function unmark(lists: unknown, p: number): ListItem[];
export function parasIn(content: string, start: number, end: number): [number, number];
export function toggleList(lists: unknown, content: string, start: number, end: number, type: string): ListItem[];
export function nestList(lists: unknown, content: string, start: number, end: number, delta: number): ListItem[];
export function listAt(lists: unknown, p: number): ListItem | null;
export function autoList(lists: ListItem[], value: string, caret: number): { value: string; caret: number; lists: ListItem[] } | null;
